CREATE OR REPLACE FUNCTION private.dic_confirm_coffee_existing(mid uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 u uuid:=private.require_member(); prior private.mutation_receipts; s public.coffee_submissions;
 target public.coffees; sid uuid; cid uuid; match_result jsonb; accepted boolean;
 req_hash text; response jsonb; a_name text; b_name text;
begin
 if mid is null or jsonb_typeof(p) is distinct from 'object' or octet_length(p::text)>5000 then
  raise exception using errcode='22023',message='Invalid coffee confirmation.';
 end if;
 sid:=(p->>'submission_id')::uuid;cid:=(p->>'coffee_id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended(u::text,9311));
 req_hash:=encode(sha256(convert_to(jsonb_build_object('action','confirm_coffee_existing','payload',p)::text,'UTF8')),'hex');
 select * into prior from private.mutation_receipts where owner_id=u and mutation_id=mid;
 if found then
  if prior.request_hash<>req_hash then raise exception using errcode='22023',message='Mutation ID reused for other confirmation.';end if;
  return prior.response;
 end if;
 select * into s from public.coffee_submissions where id=sid and owner_id=u for update;
 select * into target from public.coffees where id=cid and verification_state='verified' and merged_into_id is null;
 if s.id is null or target.id is null then raise exception using errcode='42501',message='Coffee is not accessible.';end if;
 if private.dic_canonical_roaster_key(s.proposed_data->>'roaster') is distinct from
   private.dic_canonical_roaster_key(target.roaster) then
   raise exception using errcode='23514',message='Different roasters cannot be merged based on a fuzzy name.';
 end if;
 a_name:=private.dic_coffee_key(s.proposed_data->>'name');
 b_name:=private.dic_coffee_key(target.name);
 if (a_name<>b_name and extensions.similarity(a_name,b_name)<0.60) then
  raise exception using errcode='23514',message='The names are too different for self-confirmed merging.';
 end if;
 if nullif(btrim(s.proposed_data->>'release_label'),'') is not null
    and nullif(btrim(target.release_label),'') is not null
    and private.dic_coffee_key(s.proposed_data->>'release_label')<>private.dic_coffee_key(target.release_label) then
  raise exception using errcode='23514',message='Different releases require administrator review.';
 end if;
 if nullif(btrim(s.proposed_data->>'origin'),'') is not null
    and nullif(btrim(target.origin),'') is not null
    and private.dic_coffee_key(s.proposed_data->>'origin')<>private.dic_coffee_key(target.origin)
    and position(private.dic_coffee_key(s.proposed_data->>'origin') in private.dic_coffee_key(target.origin))=0
    and position(private.dic_coffee_key(target.origin) in private.dic_coffee_key(s.proposed_data->>'origin'))=0 then
  raise exception using errcode='23514',message='Conflicting origins require administrator review.';
 end if;
 response:=private.dic_link_pending_coffee(sid,cid,'user_confirmed',
  jsonb_build_object('requested_name',s.proposed_data->>'name','canonical_name',target.name));
 insert into private.mutation_receipts(owner_id,mutation_id,request_hash,response)
 values(u,mid,req_hash,response);
 return response;
end $function$

CREATE OR REPLACE FUNCTION private.dic_edit_my_coffee(p_library_entry uuid, p_expected_revision bigint, p_details jsonb, p_source_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 u uuid:=private.require_member();
 lib public.library_entries; sub public.coffee_submissions; canonical public.coffees;
 clean jsonb; k text; value text; name_text text; roaster_text text; url_text text;
 updated_id uuid;
begin
 if p_library_entry is null or p_expected_revision is null or p_expected_revision<1 or
    jsonb_typeof(p_details) is distinct from 'object' or octet_length(p_details::text)>8000 then
   raise exception using errcode='22023',message='Invalid coffee edit request.';
 end if;
 for k in select jsonb_object_keys(p_details) loop
  if k not in ('name','roaster','release_label','origin','roast_level',
      'elevation_m','process','is_decaf','decaffeination_method','variety','producer','tasting_notes') then
   raise exception using errcode='22023',message='Unsupported coffee detail.';
  end if;
  if k='is_decaf' then
   if jsonb_typeof(p_details->k) is distinct from 'boolean' then
    raise exception using errcode='22023',message='Decaf flag must be a boolean.';
   end if;
  else
   if jsonb_typeof(p_details->k) not in ('null','string') then
    raise exception using errcode='22023',message='Coffee details must be text.';
   end if;
   value:=nullif(btrim(p_details->>k),'');
   if length(value)>(case when k='tasting_notes' then 2000 else 300 end) then
    raise exception using errcode='22023',message='Coffee detail is too long.';
   end if;
  end if;
 end loop;
 name_text:=nullif(btrim(p_details->>'name'),'');
 roaster_text:=nullif(btrim(p_details->>'roaster'),'');
 if name_text is null or length(name_text)>200 or roaster_text is null or length(roaster_text)>200 then
  raise exception using errcode='22023',message='Coffee name and roaster are required.';
 end if;
 if nullif(btrim(p_details->>'roast_level'),'') is not null
   and p_details->>'roast_level' not in
      ('Ultra Light','Very Light','Light','Medium-Light','Medium','Medium-Dark','Dark') then
  raise exception using errcode='22023',message='Choose a recognized roast level.';
 end if;
 if p_details ? 'decaffeination_method' and
    nullif(btrim(p_details->>'decaffeination_method'),'') is not null and
    p_details->>'decaffeination_method' not in ('Water Process','Sugar Process','Carbon Dioxide (CO2)') then
   raise exception using errcode='22023',message='Unknown decaffeination method.';
 end if;
 if p_details ? 'is_decaf' and p_details->>'is_decaf'='true' and
    name_text ~* '(^|[^[:alnum:]])(half[ -]?caf|semi[ -]?decaf|partially[ -]?decaf)' then
   raise exception using errcode='22023',message='Half-caf cannot be marked fully decaf.';
 end if;
 url_text:=nullif(btrim(p_source_url),'');
 if url_text is not null and (length(url_text)>4000 or url_text !~ '^https://[^[:space:]/?#]+') then
   raise exception using errcode='22023',message='Source URL must be HTTPS.';
 end if;
 clean:=jsonb_build_object(
  'name',name_text,'roaster',roaster_text,
  'release_label',nullif(btrim(p_details->>'release_label'),''),
  'origin',nullif(btrim(p_details->>'origin'),''),
  'roast_level',nullif(btrim(p_details->>'roast_level'),''),
  'elevation_m',nullif(btrim(p_details->>'elevation_m'),''),
  'process',nullif(btrim(p_details->>'process'),''),
  'variety',nullif(btrim(p_details->>'variety'),''),
  'producer',nullif(btrim(p_details->>'producer'),''),
  'tasting_notes',nullif(btrim(p_details->>'tasting_notes'),'')
 );
 -- New fields are additive. Older clients that omit them preserve previously
 -- submitted details. Explicit False removes a stale decaf method.
 if p_details ? 'is_decaf' or p_details ? 'decaffeination_method' then
  clean:=clean||jsonb_build_object(
   'is_decaf',coalesce((p_details->>'is_decaf')::boolean,
      name_text ~* '(^|[^[:alnum:]])decaf(feinated)?([^[:alnum:]]|$)')
      and name_text !~* '(^|[^[:alnum:]])(half[ -]?caf|semi[ -]?decaf|partially[ -]?decaf)',
   'decaffeination_method',case when
     coalesce((p_details->>'is_decaf')::boolean,
      name_text ~* '(^|[^[:alnum:]])decaf(feinated)?([^[:alnum:]]|$)')
      and name_text !~* '(^|[^[:alnum:]])(half[ -]?caf|semi[ -]?decaf|partially[ -]?decaf)'
     then nullif(btrim(p_details->>'decaffeination_method'),'') else null end
  );
 end if;
 select * into lib from public.library_entries
    where id=p_library_entry and owner_id=u and hidden_at is null for update;
 if lib.id is null then raise exception using errcode='42501',message='Coffee is not in your library.';end if;

 if lib.coffee_id is null then
  select * into sub from public.coffee_submissions
    where id=lib.submission_id and owner_id=u for update;
  if sub.id is null or sub.status<>'pending' then
   raise exception using errcode='23514',message='This submission is no longer editable.';
  end if;
  if sub.revision<>p_expected_revision then
   return jsonb_build_object('ok',false,'code','conflict','revision',sub.revision);
  end if;
  update public.coffee_submissions
  set proposed_data=(sub.proposed_data || clean),source_url=url_text
  where id=sub.id returning id into updated_id;
  return jsonb_build_object('ok',true,'kind','updated_pending','submission_id',updated_id);
 end if;

 select * into canonical from public.coffees
   where id=lib.coffee_id and verification_state='verified' for share;
 if canonical.id is null then
  raise exception using errcode='23514',message='The verified coffee is unavailable.';
 end if;
 -- Reuse a still-pending correction to avoid duplicate queue entries. Editing a
 -- correction never changes the verified source or this member's shot history.
 select * into sub from public.coffee_submissions
 where owner_id=u and canonical_coffee_id=canonical.id and status='pending'
 order by updated_at desc,id desc limit 1 for update;
 if sub.id is not null then
  if p_expected_revision<>sub.revision then
   return jsonb_build_object('ok',false,'code','conflict','revision',sub.revision);
  end if;
  -- Old clients omit both additive keys. Preserve previously submitted
  -- decaf details when updating an existing canonical correction too.
  if not (p_details ? 'is_decaf' or p_details ? 'decaffeination_method') then
   clean:=clean||(select coalesce(jsonb_object_agg(e.key,e.value),'{}'::jsonb)
    from jsonb_each(sub.proposed_data) e
    where e.key in ('is_decaf','decaffeination_method'));
  end if;
  update public.coffee_submissions set proposed_data=clean,source_url=url_text,
   base_coffee_revision=canonical.revision where id=sub.id returning id into updated_id;
 else
  if p_expected_revision<>canonical.revision then
   return jsonb_build_object('ok',false,'code','conflict','revision',canonical.revision);
  end if;
  insert into public.coffee_submissions(
    owner_id,canonical_coffee_id,base_coffee_revision,proposed_data,source_url,status
  ) values(u,canonical.id,canonical.revision,clean,url_text,'pending')
  returning id into updated_id;
 end if;
 return jsonb_build_object('ok',true,'kind','correction_requested','submission_id',updated_id);
end $function$

CREATE OR REPLACE FUNCTION private.dic_member_retry_pending_approval(p_submission_id uuid, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; s public.coffee_submissions; candidates jsonb;
begin
 actor:=private.require_member();
 if actor is null or p_submission_id is null or p_expected_revision is null then
  raise exception using errcode='42501',message='Signed-in member and exact Pending record required.';
 end if;
 select * into s from public.coffee_submissions where id=p_submission_id for update;
 if not found or s.owner_id is distinct from actor then
  raise exception using errcode='42501',message='Only the submission owner may retry approval.';
 end if;
 if s.revision is distinct from p_expected_revision then
  return jsonb_build_object('ok',false,'code','conflict','status',s.status,
   'message','Submission changed; refresh before retry.');
 end if;
 if s.status in ('approved','merged') and s.canonical_coffee_id is not null then
  return jsonb_build_object('ok',true,'status','verified','coffee_id',s.canonical_coffee_id,'already_verified',true);
 end if;
 if s.status not in ('pending','conflict') or s.canonical_coffee_id is not null then
  raise exception using errcode='23514',message='Only an unresolved new coffee may be retried.';
 end if;
 candidates:=private.dic_find_coffee_matches(s.proposed_data||jsonb_build_object('source_url',s.source_url));
 if candidates->>'classification'='needs_confirmation' then
  return jsonb_build_object('ok',false,'code','needs_confirmation','status','pending',
    'candidates',coalesce(candidates->'candidates','[]'::jsonb));
 end if;
 if candidates->>'classification'='exact_verified' then
  return private.dic_link_pending_coffee(s.id,(candidates->>'exact_id')::uuid,'canonical_reused',
   jsonb_build_object('method','member_auto_approved','source_assurance','member_supplied_unverified'));
 end if;
 return private.dic_promote_pending_coffee(s.id,'member_auto_approved',
   jsonb_build_object('approval_basis','member_retry_distinct',
    'source_assurance','member_supplied_unverified'),false);
end $function$

CREATE OR REPLACE FUNCTION private.dic_shared_preview_claim(account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 rec private.dic_url_preview_attempts;
 clock timestamptz:=now();
begin
 if account_id is null or not exists(select 1 from auth.users u where u.id=account_id)
 then return jsonb_build_object('allowed',false,'reason','unknown_account');end if;
 -- Database-authoritative admin; require active admission and verified email.
 -- No untrusted client privilege flag or caller-supplied administrative role.
 if exists(
   select 1 from private.app_admins a
   join private.beta_members m on m.owner_id=a.owner_id
   join auth.users u on u.id=a.owner_id
   where a.owner_id=account_id and m.enabled and m.admitted_at is not null
     and u.email_confirmed_at is not null
 ) then return jsonb_build_object('allowed',true,'unlimited',true);end if;
 insert into private.dic_url_preview_attempts(owner_id,window_started_at,last_attempt_at,attempts)
 values(account_id,clock,clock-interval '1 minute',0)
 on conflict(owner_id) do nothing;
 select * into strict rec from private.dic_url_preview_attempts
 where owner_id=account_id for update;
 if rec.window_started_at<clock-interval '24 hours' then
  update private.dic_url_preview_attempts
   set window_started_at=clock,last_attempt_at=clock,attempts=1
   where owner_id=account_id;
  return jsonb_build_object('allowed',true);
 end if;
 if rec.attempts>=12 then return jsonb_build_object('allowed',false,'reason','daily_preview_limit');end if;
 if rec.last_attempt_at>clock-interval '15 seconds'
 then return jsonb_build_object('allowed',false,'reason','preview_cooldown');end if;
 update private.dic_url_preview_attempts
  set attempts=rec.attempts+1,last_attempt_at=clock
  where owner_id=account_id;
 return jsonb_build_object('allowed',true);
end $function$

CREATE OR REPLACE FUNCTION public.dic_claim_universal_preview()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=auth.uid();
begin
 if me is null
  or auth.role() is distinct from 'authenticated'
  or not private.is_member() then
  return jsonb_build_object('allowed',false,'reason','admitted_member_required');
 end if;
 if not exists(select 1 from auth.users u where u.id=me
  and u.email_confirmed_at is not null) then
  return jsonb_build_object('allowed',false,'reason','verify_email');
 end if;
 return private.dic_shared_preview_claim(me);
end $function$
